DO $scope$ BEGIN PERFORM 1 FROM public.cafes WHERE id='3813425d-db13-4d30-8b82-9d41aad12e36' AND slug='brand-8ad185ee82e3' AND status='active' AND is_public AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Dabab identity changed';END IF;PERFORM 1 FROM public.menu_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' FOR UPDATE;PERFORM 1 FROM public.menu_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' FOR UPDATE;PERFORM 1 FROM public.cafe_settings WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' FOR UPDATE;PERFORM 1 FROM public.cafe_custom_identity WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' FOR UPDATE;IF NOT platform_access_private.service_enabled('3813425d-db13-4d30-8b82-9d41aad12e36','menu') THEN RAISE EXCEPTION 'Menu service unavailable';END IF;END $scope$;
DO $guards$ BEGIN IF(SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id)::text,'')) FROM public.menu_products p WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') IS DISTINCT FROM '2cc7ff8ecf23986f7511797bdadc45b1' OR(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id)::text,'')) FROM public.menu_categories c WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') IS DISTINCT FROM 'f66c4bfdfe6456ce3c90247f50b1dabb' THEN RAISE EXCEPTION 'Catalog changed since reviewed backup';END IF;IF(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'target',c.confrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid),'deleteAction',c.confdeltype) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c WHERE c.contype='f' AND c.confrelid IN('public.menu_products'::regclass,'public.menu_categories'::regclass)) IS DISTINCT FROM '[{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id)","deleteAction":"a","name":"bf_document_lines_product_id_fkey","table":"bf_document_lines","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id)","deleteAction":"a","name":"bf_item_product_links_product_id_fkey","table":"bf_item_product_links","target":"menu_products"},{"definition":"FOREIGN KEY (menu_product_id) REFERENCES menu_products(id)","deleteAction":"a","name":"bf_items_menu_product_id_fkey","table":"bf_items","target":"menu_products"},{"definition":"FOREIGN KEY (reward_product_id) REFERENCES menu_products(id) ON DELETE SET NULL","deleteAction":"n","name":"cafe_loyalty_programs_reward_product_id_fkey","table":"cafe_loyalty_programs","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id) ON DELETE CASCADE","deleteAction":"c","name":"event_ticket_settings_product_id_fkey","table":"event_ticket_settings","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id) ON DELETE SET NULL","deleteAction":"n","name":"event_tickets_product_id_fkey","table":"event_tickets","target":"menu_products"},{"definition":"FOREIGN KEY (reward_product_id) REFERENCES menu_products(id) ON DELETE SET NULL","deleteAction":"n","name":"experience_campaigns_reward_product_id_fkey","table":"experience_campaigns","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id) ON DELETE RESTRICT","deleteAction":"r","name":"experience_reward_items_product_id_fkey","table":"experience_reward_items","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id)","deleteAction":"a","name":"gift_order_lines_product_id_fkey","table":"gift_order_lines","target":"menu_products"},{"definition":"FOREIGN KEY (category_id) REFERENCES menu_categories(id) ON DELETE SET NULL","deleteAction":"n","name":"menu_products_category_id_fkey","table":"menu_products","target":"menu_categories"},{"definition":"FOREIGN KEY (linked_product_id) REFERENCES menu_products(id) ON DELETE SET NULL","deleteAction":"n","name":"offers_linked_product_id_fkey","table":"offers","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id) ON DELETE SET NULL","deleteAction":"n","name":"order_items_product_id_fkey","table":"order_items","target":"menu_products"},{"definition":"FOREIGN KEY (product_id) REFERENCES menu_products(id) ON DELETE CASCADE","deleteAction":"c","name":"product_media_product_id_fkey","table":"product_media","target":"menu_products"},{"definition":"FOREIGN KEY (service_id) REFERENCES menu_products(id)","deleteAction":"a","name":"salon_announcements_service_id_fkey","table":"salon_announcements","target":"menu_products"},{"definition":"FOREIGN KEY (service_id) REFERENCES menu_products(id)","deleteAction":"a","name":"salon_bookings_service_id_fkey","table":"salon_bookings","target":"menu_products"}]'::jsonb THEN RAISE EXCEPTION 'Catalog foreign keys changed';END IF;IF EXISTS(SELECT 1 FROM public.bf_document_lines r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: bf_document_lines';END IF;IF EXISTS(SELECT 1 FROM public.bf_item_product_links r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: bf_item_product_links';END IF;IF EXISTS(SELECT 1 FROM public.bf_items r JOIN public.menu_products p ON r.menu_product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: bf_items';END IF;IF EXISTS(SELECT 1 FROM public.cafe_loyalty_programs r JOIN public.menu_products p ON r.reward_product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: cafe_loyalty_programs';END IF;IF EXISTS(SELECT 1 FROM public.event_ticket_settings r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: event_ticket_settings';END IF;IF EXISTS(SELECT 1 FROM public.event_tickets r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: event_tickets';END IF;IF EXISTS(SELECT 1 FROM public.experience_campaigns r JOIN public.menu_products p ON r.reward_product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: experience_campaigns';END IF;IF EXISTS(SELECT 1 FROM public.experience_reward_items r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Historical reference appeared: experience_reward_items';END IF;IF EXISTS(SELECT 1 FROM public.gift_order_lines r JOIN public.menu_products p ON r.product_id=p.id WHERE p.cafe_id='3813425d-db13-4d30-8b82-9d41a